create type discovery_candidate_type as enum ('SIGNAL','PATTERN','THEME_CANDIDATE','CONTRADICTION');
create type discovery_status as enum ('INBOX','REVIEWING','ACCEPTED','DISMISSED');
create table themes (id uuid primary key default gen_random_uuid(), name text not null unique, description text, status text not null default 'CANDIDATE', entity_ids uuid[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table research_events (id uuid primary key default gen_random_uuid(), title text not null, occurred_at timestamptz, description text, entity_ids uuid[] not null default '{}', source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table relationships (id uuid primary key default gen_random_uuid(), from_entity_id uuid not null references entities(id), to_entity_id uuid not null references entities(id), type text not null, confidence numeric check (confidence between 0 and 1), evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now(), check (from_entity_id <> to_entity_id));
create table discovery_candidates (id uuid primary key default gen_random_uuid(), type discovery_candidate_type not null, title text not null, description text not null, status discovery_status not null default 'INBOX', confidence numeric not null check (confidence between 0 and 1), theme_id uuid references themes(id), company_ids uuid[] not null default '{}', source_ids uuid[] not null default '{}', claim_ids uuid[] not null default '{}', evidence_ids uuid[] not null default '{}', tags text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index discovery_candidates_theme_idx on discovery_candidates(theme_id);
create index discovery_candidates_status_idx on discovery_candidates(status);
